// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.getTokens();
        uint256 toGive = c.value() / 100000 * 99999;
        // The reference sets blacklist[investor] = true when toGive > 0, the buggy does not.
        assertTrue(!(toGive > 0 && c.blacklist(caller) == false));
    }
}

